import { userAccountData, diskSelectionData } from '$lib/state.svelte';
import { PAGE_IDS, PAGES_NEEDING_VALIDATION } from '$lib/types';
import type { PageID } from '$lib/types';
import { t } from '$lib/i18n';
// @ts-expect-error — generated by Wails
import { SetCurrentPage, ValidateUserAccount, SaveUserAccount, ValidateDiskSelection, SaveDiskSelection, RebootAndClose } from '@wails/go/gui/App.js';
// @ts-expect-error — generated by Wails
import { gui } from '@wails/go/models';

// Page-specific error messages for validation failures
const PAGE_ERROR_MESSAGES: Record<PageID, string> = {
	[PAGE_IDS.WELCOME]: t('validation.selectLanguage'),
	[PAGE_IDS.USER_ACCOUNT]: t('validation.selectUserAccount'),
	[PAGE_IDS.DISK_SELECTION]: t('validation.selectDisk'),
	[PAGE_IDS.CONFIRMATION]: t('validation.reviewInstallation'),
	[PAGE_IDS.INSTALLATION]: t('validation.waitInstallation'),
	[PAGE_IDS.FINISH]: t('validation.installationComplete'),
};

export async function goNext(currentPage: number): Promise<string | null> {
	// Validate current page if needed
	if (PAGES_NEEDING_VALIDATION.has(currentPage as PageID)) {
		const validationError = await validateCurrentPage(currentPage);
		if (validationError) return validationError;
	}

	// Commit (save) page data after validation passes
	await commitPageData(currentPage);

	// Update backend
	const nextPage = currentPage + 1;
	await SetCurrentPage(new gui.PageID({ Value: nextPage }));

	return null; // Success
}

export async function goBack(currentPage: number): Promise<string | null> {
	// Reset disk selection when going back from ConfirmationPage
	if (currentPage === PAGE_IDS.CONFIRMATION) {
		diskSelectionData.diskId = '';
		diskSelectionData.disk = null;
	}

	// Update backend
	const prevPage = currentPage - 1;
	await SetCurrentPage(new gui.PageID({ Value: prevPage }));

	return null; // Success
}

export async function finish(): Promise<string | null> {
	try {
		await RebootAndClose();
		return null;
	} catch (err) {
		return err instanceof Error ? err.message : 'Failed to reboot';
	}
}

async function validateCurrentPage(page: number): Promise<string | null> {
	try {
		if (page === PAGE_IDS.USER_ACCOUNT) {
			await ValidateUserAccount({
				username: userAccountData.username,
				password: userAccountData.password,
				confirmPassword: userAccountData.confirmPassword,
			});
		}

		if (page === PAGE_IDS.DISK_SELECTION) {
			await ValidateDiskSelection({
				diskId: diskSelectionData.diskId,
				size: diskSelectionData.disk?.size ?? '',
				fileSystem: diskSelectionData.fileSystem,
			});
		}

		return null; // Validation passed
	} catch {
		return PAGE_ERROR_MESSAGES[page as PageID] ?? 'Please fix the issues above to continue.';
	}
}

// CommitPageData validates AND saves page data. Called after validation passes.
// This is a workflow operation, not a pure validation.
async function commitPageData(page: number): Promise<void> {
	if (page === PAGE_IDS.USER_ACCOUNT) {
		await SaveUserAccount({
			username: userAccountData.username,
			password: userAccountData.password,
			confirmPassword: userAccountData.confirmPassword,
		});
	}

	if (page === PAGE_IDS.DISK_SELECTION) {
		await SaveDiskSelection({
			diskId: diskSelectionData.diskId,
			size: diskSelectionData.disk?.size ?? '',
			fileSystem: diskSelectionData.fileSystem,
		});
	}
}
